import { buildMidiFile, midiNotesFromMusicXml } from "./midi";

const SCALE_XML = `<?xml version="1.0" encoding="UTF-8"?>
<score-partwise version="4.0">
  <movement-title>Test</movement-title>
  <part-list><score-part id="P1"><part-name>Horn</part-name></score-part></part-list>
  <part id="P1">
    <measure number="1">
      <attributes><divisions>1</divisions><key><fifths>0</fifths></key>
        <time><beats>4</beats><beat-type>4</beat-type></time></attributes>
      <sound tempo="120"/>
      <note id="hs-sn-000001-1"><pitch><step>C</step><octave>4</octave></pitch><duration>1</duration><type>quarter</type></note>
      <note id="hs-sn-000002-1"><pitch><step>E</step><octave>4</octave></pitch><duration>1</duration><type>quarter</type></note>
      <note id="hs-sn-000003-1"><pitch><step>G</step><octave>4</octave></pitch><duration>2</duration><type>half</type></note>
    </measure>
  </part>
</score-partwise>`;

const TIED_XML = `<?xml version="1.0"?>
<score-partwise><part-list><score-part id="P1"><part-name>x</part-name></score-part></part-list>
  <part id="P1">
    <measure number="1"><attributes><divisions>2</divisions></attributes>
      <sound tempo="60"/>
      <note><pitch><step>D</step><octave>4</octave></pitch><duration>2</duration><tie type="start"/></note>
      <note><pitch><step>D</step><octave>4</octave></pitch><duration>2</duration><tie type="stop"/></note>
      <note><rest/><duration>1</duration></note>
      <note><pitch><step>F</step><alter>1</alter><octave>4</octave></pitch><duration>1</duration></note>
    </measure>
  </part>
</score-partwise>`;

describe("midiNotesFromMusicXml", () => {
  it("maps quarter/half durations to 480-tick onsets", () => {
    const { notes, tempoBpm, meter } = midiNotesFromMusicXml(SCALE_XML);
    expect(tempoBpm).toBe(120);
    expect(meter).toBe("4/4");
    expect(notes).toEqual([
      { on: 0, off: 480, midi: 60 },
      { on: 480, off: 960, midi: 64 },
      { on: 960, off: 1920, midi: 67 },
    ]);
  });

  it("merges tie start/stop pairs into one sustained note", () => {
    const { notes, tempoBpm } = midiNotesFromMusicXml(TIED_XML);
    expect(tempoBpm).toBe(60);
    // divisions=2: D4 spans 4 divisions = 960 ticks; F#4 follows a rest.
    expect(notes).toEqual([
      { on: 0, off: 960, midi: 62 },
      { on: 1200, off: 1440, midi: 66 },
    ]);
  });

  it("throws on malformed XML", () => {
    expect(() => midiNotesFromMusicXml("<score-partwise><part>")).toThrow();
  });
});

describe("buildMidiFile", () => {
  it("emits a valid SMF header and track chunk", () => {
    const bytes = buildMidiFile(SCALE_XML);
    // MThd, len 6, format 0, 1 track, 480 tpq
    expect(Array.from(bytes.slice(0, 4))).toEqual([0x4d, 0x54, 0x68, 0x64]);
    expect(Array.from(bytes.slice(4, 8))).toEqual([0, 0, 0, 6]);
    expect(Array.from(bytes.slice(8, 14))).toEqual([0, 0, 0, 1, 0x01, 0xe0]);
    expect(Array.from(bytes.slice(14, 18))).toEqual([0x4d, 0x54, 0x72, 0x6b]);
    const trackLen =
      (bytes[18] << 24) | (bytes[19] << 16) | (bytes[20] << 8) | bytes[21];
    expect(trackLen).toBe(bytes.length - 22);
    // End-of-track meta event is the last three bytes.
    expect(Array.from(bytes.slice(-3))).toEqual([0xff, 0x2f, 0x00]);
  });

  it("contains a tempo meta event for 120bpm (500000us/qn)", () => {
    const bytes = buildMidiFile(SCALE_XML);
    const body = Array.from(bytes);
    const idx = body.findIndex(
      (_, i) =>
        body[i] === 0xff && body[i + 1] === 0x51 && body[i + 2] === 0x03,
    );
    expect(idx).toBeGreaterThan(-1);
    const us = (body[idx + 3] << 16) | (body[idx + 4] << 8) | body[idx + 5];
    expect(us).toBe(500000);
  });

  it("emits program change + note on/off pairs", () => {
    const bytes = buildMidiFile(SCALE_XML);
    const body = Array.from(bytes);
    expect(body).toContain(0xc0);
    const noteOns = body.filter((b, i) => b === 0x90 && body[i + 2] === 80);
    const noteOffs = body.filter((b) => b === 0x80);
    expect(noteOns.length).toBe(3);
    expect(noteOffs.length).toBe(3);
  });
});

/**
 * MusicXML → SMF (Standard MIDI File, format 0) builder for the
 * 再生用MIDI export (#99).
 *
 * Pure-JS: parses the concert-pitch MusicXML with DOMParser, walks the
 * note stream honouring <chord/>, <backup>/<forward>, per-measure
 * <divisions>, tie merge (start/stop pairs become one sustained note)
 * and the <sound tempo> / <time> meta events, then serializes a
 * single-track SMF at 480 ticks per quarter.
 *
 * Scope: single-part monophonic output (the engine's contract); chord
 * members and multi-voice <backup> content are still emitted correctly
 * since the walking algorithm is generic.
 */

const TICKS_PER_QUARTER = 480;
/** GM program 60 = French Horn (0-indexed program change byte). */
const HORN_PROGRAM = 60;
const DEFAULT_VELOCITY = 80;

interface MidiNote {
  /** Absolute onset in ticks. */
  on: number;
  /** Absolute release in ticks (> on). */
  off: number;
  midi: number;
}

const STEP_TO_SEMITONE: Record<string, number> = {
  C: 0,
  D: 2,
  E: 4,
  F: 5,
  G: 7,
  A: 9,
  B: 11,
};

function noteMidi(el: Element): number | null {
  const pitch = el.querySelector(":scope > pitch");
  if (!pitch) return null;
  const step = pitch.querySelector("step")?.textContent ?? "";
  const base = STEP_TO_SEMITONE[step];
  const octaveText = pitch.querySelector("octave")?.textContent;
  if (base === undefined || octaveText == null) return null;
  const alter = Number(pitch.querySelector("alter")?.textContent ?? 0);
  const octave = Number(octaveText);
  if (!Number.isFinite(alter) || !Number.isFinite(octave)) return null;
  return base + alter + (octave + 1) * 12;
}

function varLen(value: number): number[] {
  let v = Math.max(0, Math.floor(value));
  const out = [v & 0x7f];
  v >>= 7;
  while (v > 0) {
    out.unshift((v & 0x7f) | 0x80);
    v >>= 7;
  }
  return out;
}

function u16(v: number): number[] {
  return [(v >> 8) & 0xff, v & 0xff];
}
function u32(v: number): number[] {
  return [(v >> 24) & 0xff, (v >> 16) & 0xff, (v >> 8) & 0xff, v & 0xff];
}

/** Tempo BPM → microseconds-per-quarter meta event body. */
function tempoMeta(bpm: number): number[] {
  const us = Math.round(60_000_000 / bpm);
  return [0xff, 0x51, 0x03, (us >> 16) & 0xff, (us >> 8) & 0xff, us & 0xff];
}

/** Time-signature meta event body for "n/d" (d must be a power of 2). */
function timeSigMeta(meter: string | null): number[] | null {
  if (!meter) return null;
  const [n, d] = meter.split("/").map(Number);
  if (!Number.isFinite(n) || !Number.isFinite(d) || n <= 0 || d <= 0) {
    return null;
  }
  const dd = Math.round(Math.log2(d));
  if (2 ** dd !== d) return null;
  return [0xff, 0x58, 0x04, n & 0xff, dd & 0xff, 24, 8];
}

/**
 * Parse the concert MusicXML into absolute-tick note events.
 * Throws on malformed XML (same policy as parseScoreDoc).
 */
export function midiNotesFromMusicXml(xml: string): {
  notes: MidiNote[];
  tempoBpm: number;
  meter: string | null;
} {
  const doc = new DOMParser().parseFromString(xml, "application/xml");
  if (doc.querySelector("parsererror")) {
    throw new Error("MusicXML parse failed");
  }
  const tempoText = doc.querySelector("sound[tempo]")?.getAttribute("tempo");
  const tempoBpm =
    tempoText != null && Number.isFinite(Number(tempoText)) && Number(tempoText) > 0
      ? Number(tempoText)
      : 120;
  const beats = doc.querySelector("time > beats")?.textContent?.trim();
  const beatType = doc.querySelector("time > beat-type")?.textContent?.trim();
  const meter = beats && beatType ? `${beats}/${beatType}` : null;

  const notes: MidiNote[] = [];
  // pitch → open tie note (start/stop chains merge into one event).
  const openTies = new Map<number, MidiNote>();
  // Per-part walk so <backup> only rewinds its own part's cursor.
  for (const part of Array.from(doc.querySelectorAll("part"))) {
    let divisions = 1; // quarter-note units per <duration> tick
    let cursor = 0;   // divisions
    for (const measure of Array.from(part.querySelectorAll(":scope > measure"))) {
      for (const el of Array.from(measure.children)) {
        if (el.tagName === "attributes") {
          const d = el.querySelector("divisions")?.textContent;
          if (d != null && Number.isFinite(Number(d)) && Number(d) > 0) {
            divisions = Number(d);
          }
          continue;
        }
        if (el.tagName === "backup" || el.tagName === "forward") {
          const dur = Number(el.querySelector("duration")?.textContent ?? 0);
          if (Number.isFinite(dur)) {
            cursor += el.tagName === "backup" ? -dur : dur;
            if (cursor < 0) cursor = 0;
          }
          continue;
        }
        if (el.tagName !== "note") continue;

        const isChord = el.querySelector(":scope > chord") !== null;
        const dur = Number(el.querySelector(":scope > duration")?.textContent ?? 0);
        const isRest = el.querySelector(":scope > rest") !== null;
        const isGrace = el.querySelector(":scope > grace") !== null;
        const midi = isRest || isGrace ? null : noteMidi(el);

        if (midi !== null && dur > 0) {
          const onTick = Math.round((cursor * TICKS_PER_QUARTER) / divisions);
          const offTick = Math.round(
            ((cursor + dur) * TICKS_PER_QUARTER) / divisions,
          );
          const tieStart =
            el.querySelector('tie[type="start"]') !== null;
          const tieStop = el.querySelector('tie[type="stop"]') !== null;
          const open = openTies.get(midi);
          if (tieStop && open && open.on < onTick) {
            // Continuation: extend the open note instead of re-striking.
            open.off = Math.max(open.off, offTick);
            if (!tieStart) openTies.delete(midi);
          } else {
            const note: MidiNote = { on: onTick, off: offTick, midi };
            notes.push(note);
            if (tieStart) openTies.set(midi, note);
          }
        }
        // Chord members share the previous note's onset: the cursor
        // only advances for non-chord notes.
        if (!isChord && Number.isFinite(dur)) cursor += dur;
      }
    }
  }
  notes.sort((a, b) => a.on - b.on || a.midi - b.midi);
  return { notes, tempoBpm, meter };
}

/** Serialize parsed notes into an SMF format-0 byte array. */
export function buildMidiFile(xml: string): Uint8Array {
  const { notes, tempoBpm, meter } = midiNotesFromMusicXml(xml);

  // Flatten into (tick, order, bytes) events; note-offs sort before
  // note-ons at the same tick so a boundary never overlaps itself.
  interface Ev { tick: number; order: number; bytes: number[] }
  const events: Ev[] = [];
  const meta = [tempoMeta(tempoBpm), timeSigMeta(meter)].filter(
    (m): m is number[] => m !== null,
  );
  for (const m of meta) events.push({ tick: 0, order: 0, bytes: m });
  events.push({ tick: 0, order: 1, bytes: [0xc0, HORN_PROGRAM] });
  for (const n of notes) {
    events.push({
      tick: n.on,
      order: 2,
      bytes: [0x90, n.midi & 0x7f, DEFAULT_VELOCITY],
    });
    events.push({
      tick: n.off,
      order: 1,
      bytes: [0x80, n.midi & 0x7f, 0],
    });
  }
  const lastTick = notes.reduce((m, n) => Math.max(m, n.off), 0);
  events.push({ tick: lastTick, order: 3, bytes: [0xff, 0x2f, 0x00] });
  events.sort((a, b) => a.tick - b.tick || a.order - b.order);

  const track: number[] = [];
  let prev = 0;
  for (const ev of events) {
    track.push(...varLen(ev.tick - prev), ...ev.bytes);
    prev = ev.tick;
  }

  const header = [
    0x4d, 0x54, 0x68, 0x64, // "MThd"
    ...u32(6),
    ...u16(0), // format 0
    ...u16(1), // one track
    ...u16(TICKS_PER_QUARTER),
  ];
  const trackChunk = [
    0x4d, 0x54, 0x72, 0x6b, // "MTrk"
    ...u32(track.length),
    ...track,
  ];
  return new Uint8Array([...header, ...trackChunk]);
}

/**
 * ExportPort — the seam between the 書き出し dialog and a concrete export
 * backend (UI-060).
 *
 * Same gate pattern as `src/sidecar/port.ts` (UI-040): the port owns the
 * capability probe and the export job, never the dialog logic; a real
 * implementation will wrap the sidecar client once the engine spawn bridge
 * lands, feeding `engine.handshake` capabilities into
 * {@link ExportCapabilities} (methods/jobKinds → supported formats,
 * engineInfo → diagnostics parity).
 *
 * ## Runtime gate
 *
 * `createDefaultExportPort()` returns:
 *
 * - {@link MockExportPort} in a plain browser (`vite dev` / vitest) — an
 *   in-process fake that exercises the full §17 flow including
 *   MuseScore-missing and permission-error recovery;
 * - {@link TauriExportPort} inside the Tauri webview (#99) — real
 *   MusicXML/MIDI/PDF export driven by the live score document; the
 *   `source` getter supplies the document + basename at export time.
 */

import { isTauriRuntime } from "../tauri/bridge";
import { MockExportPort } from "./mockPort";
import { TauriExportPort, type ExportSource } from "./tauriPort";
import type { ExportPort } from "./types";

// The port contract lives in types.ts with the rest of the export model.
export type { ExportPort } from "./types";

export function createDefaultExportPort(
  source?: () => ExportSource | null,
): ExportPort {
  if (isTauriRuntime()) return new TauriExportPort(source ?? (() => null));
  return MockExportPort.withDevOverrides();
}

/**
 * TauriExportPort — the real export backend inside the Tauri webview
 * (#99). MusicXML and MIDI are produced entirely client-side from the
 * live score document (user edits included via musicXml(view)); PDF
 * renders through a detected MuseScore install. No engine process is
 * required for any format.
 *
 * Rust commands (src-tauri/src/export.rs) own the privileged halves:
 * folder picking, artifact writes (granted-dir allowlist), tool
 * probing, explorer reveal and the MuseScore subprocess.
 */
import { invoke } from "@tauri-apps/api/core";
import {
  withPathOverride,
  type ToolInfo,
  type ToolPathOverrides,
} from "../diagnostics/types";
import type { ScoreDocumentPort } from "../score/document";
import { buildMidiFile } from "./midi";
import {
  ExportError,
  type ExportCapabilities,
  type ExportFormatId,
  type ExportPort,
  type ExportRequest,
  type ExportResult,
  type ExportedFile,
} from "./types";

/** ENG-001 filename policy shared with the mock port. */
const ARTIFACT_NAMES: Record<ExportFormatId, string> = {
  concertMusicxml: "concert.musicxml",
  hornMusicxml: "horn_in_f.musicxml",
  concertPdf: "concert.pdf",
  hornPdf: "horn_in_f.pdf",
  playbackMidi: "playback.mid",
};

/** What the port needs from the app at export time. */
export interface ExportSource {
  /** Live score document (XML bodies + meta); null = nothing to export. */
  readonly doc: ScoreDocumentPort | null;
  /** Default file basename — audio file stem or score title. */
  readonly basename: string;
}

interface DetectedToolWire {
  status: string;
  path?: string;
}
interface DetectedToolsWire {
  museScore: DetectedToolWire;
  ffmpeg: DetectedToolWire;
}

function toToolInfo(wire: DetectedToolWire): ToolInfo {
  return wire.status === "found"
    ? { status: "found", path: wire.path }
    : { status: "missing" };
}

/** UTF-8-safe base64 (btoa chokes on multibyte; chunk to stay under the
 *  String.fromCharCode arg limit). */
function toBase64(bytes: Uint8Array): string {
  let bin = "";
  const CHUNK = 0x8000;
  for (let i = 0; i < bytes.length; i += CHUNK) {
    bin += String.fromCharCode(...bytes.subarray(i, i + CHUNK));
  }
  return btoa(bin);
}

function textToBase64(text: string): string {
  return toBase64(new TextEncoder().encode(text));
}

/** Filesystem-safe basename: strip separators and illegal chars. */
function sanitizeBasename(raw: string): string {
  const cleaned = raw
    .replace(/[\\/:*?"<>|]/g, "_")
    .replace(/\.+$/, "")
    .trim();
  return cleaned || "score";
}

function mapInvokeError(err: unknown): ExportError {
  const msg = err instanceof Error ? err.message : String(err);
  if (msg.includes("PERMISSION_DENIED")) {
    return new ExportError("PERMISSION_DENIED", msg);
  }
  if (msg.includes("MUSESCORE_UNAVAILABLE")) {
    return new ExportError("MUSESCORE_UNAVAILABLE", msg);
  }
  return new ExportError("EXPORT_FAILED", msg);
}

export class TauriExportPort implements ExportPort {
  /** Last tool-path overrides seen by capabilities() — reused by the
   *  PDF branch of export() so a user-specified MuseScore path wins. */
  private overrides?: ToolPathOverrides;

  constructor(private readonly source: () => ExportSource | null) {}

  async capabilities(
    overrides?: ToolPathOverrides,
  ): Promise<ExportCapabilities> {
    this.overrides = overrides;
    const tools = await invoke<DetectedToolsWire>("detect_tools").catch(
      () => null,
    );
    const museScore = withPathOverride(
      tools ? toToolInfo(tools.museScore) : { status: "missing" },
      overrides?.museScorePath,
    );
    const ffmpeg = withPathOverride(
      tools ? toToolInfo(tools.ffmpeg) : { status: "missing" },
      overrides?.ffmpegPath,
    );
    return {
      // Client-side export needs no engine — report that honestly
      // rather than faking a handshake.
      engineInfo: null,
      protocolVersion: null,
      backend: null,
      museScore,
      ffmpeg,
    };
  }

  async chooseDestination(current?: string): Promise<string | null> {
    try {
      return await invoke<string | null>("export_pick_dir", {
        current: current ?? null,
      });
    } catch (err) {
      throw mapInvokeError(err);
    }
  }

  async defaultDestination(): Promise<string> {
    try {
      return await invoke<string>("export_default_dir");
    } catch (err) {
      throw mapInvokeError(err);
    }
  }

  async export(request: ExportRequest): Promise<ExportResult> {
    const source = this.source();
    if (!source?.doc) {
      throw new ExportError("EXPORT_FAILED", "no score document to export");
    }
    const basename = sanitizeBasename(
      request.basename?.trim() || source.basename || source.doc.meta.title,
    );
    const dir = request.destination;
    const files: ExportedFile[] = [];

    // Text/binary artifacts first (single batched write call).
    const batch: { format: ExportFormatId; name: string; dataBase64: string }[] = [];
    for (const format of request.formats) {
      const name = `${basename}_${ARTIFACT_NAMES[format]}`;
      if (format === "concertMusicxml") {
        batch.push({ format, name, dataBase64: textToBase64(source.doc.musicXml("concert")) });
      } else if (format === "hornMusicxml") {
        batch.push({ format, name, dataBase64: textToBase64(source.doc.musicXml("hornF")) });
      } else if (format === "playbackMidi") {
        batch.push({
          format,
          name,
          dataBase64: toBase64(buildMidiFile(source.doc.musicXml("concert"))),
        });
      }
    }
    if (batch.length > 0) {
      let paths: string[];
      try {
        paths = await invoke<string[]>("export_write_files", {
          dir,
          files: batch.map((f) => ({ name: f.name, dataBase64: f.dataBase64 })),
        });
      } catch (err) {
        throw mapInvokeError(err);
      }
      batch.forEach((f, i) =>
        files.push({ format: f.format, name: f.name, path: paths[i] ?? `${dir}\\${f.name}` }),
      );
    }

    // PDFs render through MuseScore — gated by the probe the dialog
    // already ran (a missing tool surfaces as MUSESCORE_UNAVAILABLE).
    const pdfFormats = request.formats.filter(
      (f) => f === "concertPdf" || f === "hornPdf",
    );
    if (pdfFormats.length > 0) {
      const caps = await this.capabilities(this.overrides);
      const exe = caps.museScore.status === "found" ? caps.museScore.path : null;
      if (!exe) {
        throw new ExportError(
          "MUSESCORE_UNAVAILABLE",
          "MuseScore not found; PDF export is unavailable",
        );
      }
      for (const format of pdfFormats) {
        const name = `${basename}_${ARTIFACT_NAMES[format]}`;
        const xml = source.doc.musicXml(format === "hornPdf" ? "hornF" : "concert");
        try {
          const path = await invoke<string>("render_pdf", {
            musescorePath: exe,
            musicXml: xml,
            outPath: `${dir}\\${name}`,
          });
          files.push({ format, name, path });
        } catch (err) {
          throw mapInvokeError(err);
        }
      }
    }

    return { destination: dir, files };
  }

  async revealInExplorer(path: string): Promise<boolean> {
    try {
      await invoke("reveal_in_explorer", { path });
      return true;
    } catch {
      return false;
    }
  }
}
